const msg = $input.first().json.message || {};
const text = String(msg.text || '').trim();
const chatId = msg.chat?.id || '300628321';
const fromId = msg.from?.id ? String(msg.from.id) : 'unknown';

function esc(value) {
  return String(value || '').replace(/'/g, "''");
}

function safeSelect(reply) {
  return `SELECT '${esc(reply)}'::text AS reply_text;`;
}

const unitPattern = /^CUNIT-2026-06-22-[A-Z0-9-]+$/;
const parts = text.split(/\s+/);
let command = (parts[0] || '').toLowerCase();
if (command && !command.startsWith('/')) {
  command = '/' + command;
}
const unit = parts[1] || '';
const reason = text.split(/\s+/).slice(2).join(' ').trim();

let query;
let action = 'unknown';

if (command === '/review_card' && (parts[1] || '').toLowerCase() === 'monday') {
  action = 'review_card';
  query = `
    SELECT
      (
        'BrainCoach Monday Review Card' || E'\n\n' ||
        u.platform || ' / ' || u.format || E'\n' ||
        g.content_unit_code || E'\n' ||
        'asset_type: ' || g.asset_type || E'\n' ||
        'status: ' || g.voice_check_status || ' / ' || g.approval_status || E'\n' ||
        COALESCE('window: ' || u.publishing_time_label || E'\n', '') ||
        E'\n' ||
        left(g.asset_text, 1500) ||
        E'\n\nCommands:\n' ||
        '/approve ' || g.content_unit_code || E'\n' ||
        '/needs_edit ' || g.content_unit_code || ' reason' || E'\n' ||
        '/reject ' || g.content_unit_code || ' reason'
      ) AS reply_text
    FROM production.generated_content_assets g
    JOIN production.content_units u
      ON u.content_unit_code = g.content_unit_code
    WHERE g.metadata->>'generator' = 'monday_generator_mvp1'
      AND g.metadata->>'content_plan_code' = 'CPLAN-2026-06-22-W01'
      AND g.metadata->>'planned_date' = '2026-06-22'
      AND g.approval_status IN ('pending', 'needs_edit')
    ORDER BY
      CASE u.platform
        WHEN 'Instagram' THEN 1
        WHEN 'Threads' THEN 2
        WHEN 'Facebook' THEN 3
        WHEN 'Telegram' THEN 4
        WHEN 'TikTok' THEN 5
        WHEN 'YouTube Shorts' THEN 6
        ELSE 99
      END,
      CASE u.format
        WHEN 'Reel' THEN 1
        WHEN 'Story' THEN 2
        WHEN 'Thread' THEN 3
        WHEN 'Post' THEN 4
        WHEN 'Note' THEN 5
        WHEN 'Short' THEN 6
        ELSE 99
      END,
      g.content_unit_code
    LIMIT 1;
  `;
} else if (command === '/review_status' && (parts[1] || '').toLowerCase() === 'monday') {
  action = 'review_status';
  query = "SELECT (E'Monday Review Status\\n\\n' || string_agg(approval_status || ' / ' || voice_check_status || ': ' || assets, E'\\n' ORDER BY approval_status, voice_check_status)) AS reply_text FROM (SELECT approval_status, voice_check_status, count(*) AS assets FROM production.generated_content_assets WHERE metadata->>'generator' = 'monday_generator_mvp1' AND metadata->>'content_plan_code' = 'CPLAN-2026-06-22-W01' AND metadata->>'planned_date' = '2026-06-22' GROUP BY approval_status, voice_check_status) s;";
} else if (['/approve', '/needs_edit', '/reject'].includes(command)) {
  if (!unitPattern.test(unit)) {
    query = safeSelect('Invalid or missing content_unit_code. Use CUNIT-2026-06-22-...');
  } else if ((command === '/needs_edit' || command === '/reject') && !reason) {
    query = safeSelect('Reason is required for ' + command + '.');
  } else if (command === '/approve') {
    action = 'approve';
    query = `UPDATE production.generated_content_assets AS g SET approval_status = 'approved', voice_check_status = 'passed', approved_at = now(), metadata = g.metadata || jsonb_build_object('review_status', 'approved', 'reviewed_by', 'telegram_operator', 'telegram_from_id', '${esc(fromId)}', 'reviewed_at', now()::text, 'review_channel', 'telegram_review_mvp1'), updated_at = now() WHERE g.content_unit_code = '${esc(unit)}' AND g.metadata->>'generator' = 'monday_generator_mvp1' AND g.metadata->>'content_plan_code' = 'CPLAN-2026-06-22-W01' AND g.metadata->>'planned_date' = '2026-06-22' RETURNING (E'Approved:\\n' || g.content_unit_code || E'\\n\\napproval_status = ' || g.approval_status || E'\\nvoice_check_status = ' || g.voice_check_status) AS reply_text;`;
  } else if (command === '/needs_edit') {
    action = 'needs_edit';
    query = `UPDATE production.generated_content_assets AS g SET approval_status = 'needs_edit', voice_check_status = 'needs_edit', approved_at = NULL, metadata = g.metadata || jsonb_build_object('review_status', 'needs_edit', 'review_note', '${esc(reason)}', 'reviewed_by', 'telegram_operator', 'telegram_from_id', '${esc(fromId)}', 'reviewed_at', now()::text, 'review_channel', 'telegram_review_mvp1'), updated_at = now() WHERE g.content_unit_code = '${esc(unit)}' AND g.metadata->>'generator' = 'monday_generator_mvp1' AND g.metadata->>'content_plan_code' = 'CPLAN-2026-06-22-W01' AND g.metadata->>'planned_date' = '2026-06-22' RETURNING (E'Needs edit:\\n' || g.content_unit_code || E'\\n\\nReason saved:\\n' || (g.metadata->>'review_note')) AS reply_text;`;
  } else if (command === '/reject') {
    action = 'reject';
    query = `UPDATE production.generated_content_assets AS g SET approval_status = 'rejected', voice_check_status = 'failed', approved_at = NULL, metadata = g.metadata || jsonb_build_object('review_status', 'rejected', 'review_note', '${esc(reason)}', 'reviewed_by', 'telegram_operator', 'telegram_from_id', '${esc(fromId)}', 'reviewed_at', now()::text, 'review_channel', 'telegram_review_mvp1'), updated_at = now() WHERE g.content_unit_code = '${esc(unit)}' AND g.metadata->>'generator' = 'monday_generator_mvp1' AND g.metadata->>'content_plan_code' = 'CPLAN-2026-06-22-W01' AND g.metadata->>'planned_date' = '2026-06-22' RETURNING (E'Rejected:\\n' || g.content_unit_code || E'\\n\\nReason saved:\\n' || (g.metadata->>'review_note')) AS reply_text;`;
  }
} else {
  query = safeSelect('Unknown review command. Use: review_card monday, review_status monday, approve CUNIT-..., needs_edit CUNIT-... reason, reject CUNIT-... reason');
}

return [{ json: { chat_id: chatId, command_text: text, action, content_unit_code: unit, review_note: reason, query } }];

const rows = $input.all().map(item => item.json);
const chatId = $('SYS_ParseReviewCommand').first().json.chat_id;
const original = $('SYS_ParseReviewCommand').first().json;

let reply;

if (rows.length === 0) {
  reply = [
    'No matching asset updated.',
    '',
    `Command: ${original.command_text}`,
    '',
    'Check content_unit_code and Monday generator scope.'
  ].join('\n');
} else {
  reply = rows[0].reply_text || JSON.stringify(rows[0], null, 2);
}

return [{
  json: {
    chat_id: chatId,
    reply_text: reply
  }
}];
